const nabu = slug => `https://www.nabu.de/tiere-und-pflanzen/voegel/portraets/${slug}/`;
const flora = id => `https://www.floraweb.de/php/artenhome.php?${typeof id === 'string' ? 'name-use-id' : 'suchnr'}=${id}`;
const wild = slug => `https://www.deutschewildtierstiftung.de/wildtiere/${slug}`;
const coast = 'https://www.nationalpark-wattenmeer.de/';
const colors = (body, back = body, belly = body, head = body, beak = '#30312d', legs = '#64574b', accent = '#e5e0cd') => ({body, back, belly, head, beak, legs, accent});
function animal(id, common, latin, type, form, size, habitats, zone, palette, details) {
  return {id, common, latin, type, form, size, habitats, zone, colors: palette,
    prey: [], daytime: 'day', ...details};
}
function bird(id, common, latin, form, size, habitats, zone, palette, slug, details) {
  return animal(id, common, latin, 'bird', form, size, habitats, zone, palette, {source: nabu(slug), ...details});
}
