// Added after the base records and habitat definitions, to retain saved species IDs.
// Agricultural edge species use the same identity rather than duplicate city/field variants.
for (const id of ['hare','fox','capreolus_capreolus','microtus_arvalis','alauda_arvensis','falco_tinnunculus','buteo_buteo','ciconia_ciconia','columba_palumbus','fringilla_coelebs','hirundo_rustica','bombus_lapidarius','aglais_io','coccinella_septempunctata','lumbricus_terrestris']) {
  animals.find(item => item.id === id).habitats.push('farmland');
}
for (const id of ['anas_platyrhynchos','ardea_cinerea','alcedo_atthis']) animals.find(item => item.id === id).habitats.push('forest');
animals.find(item => item.id === 'apus_apus').source = 'https://vogeltrainer.nabu.de/vogel/mauersegler/';
export const ANIMALS = Object.fromEntries(animals.map(item => [item.id, item]));
// Concrete food links apply across the species' aquatic and terrestrial habitats.
ANIMALS.ardea_cinerea.prey.push('clupea_harengus','pleuronectes_platessa','crangon_crangon');
for(const id of ['fox','buteo_buteo','falco_tinnunculus','strix_aluco']) if(ANIMALS[id]) ANIMALS[id].resource='rodents';

function plant(id, common, latin, type, form, size, habitats, layer, palette, recognition, description, concept, source) {
  return {id, common, latin, type, form, size, habitats, layer, kingdom:type === 'fungus' ? 'Fungi' : 'Plantae', colors:{leaf:palette[0],bark:palette[1]??'#70614a',flower:palette[2]??'#e4d5b6'}, recognition, description, concept, source};
}
const plants = [
  plant('fagus_sylvatica','Rotbuche','Fagus sylvatica','tree','beech',28,['forest','city'],'Baumschicht',['#4d6a34','#8a8980'], 'Glatte graue Rinde, ovale Blätter mit welligem Rand, spitze lange Knospen.', 'Buchen können durch ihr dichtes Kronendach starke Beschattung erzeugen. Junge Buchen vertragen Schatten, benötigen für kräftiges Wachstum aber zusätzliche Ressourcen. Im Herbst fallen Bucheckern und Laub auf den Boden.', 'Lichtkonkurrenz; Schattentoleranz; Energie und Stofffluss.', flora(2357)),
  plant('quercus_robur','Stieleiche','Quercus robur','tree','oak',27,['forest','city','farmland'],'Baumschicht',['#59733b','#5e5a4b'], 'Gelappte kurz gestielte Blätter; Eicheln an langen Fruchtstielen; rissige Borke.', 'Stieleichen sind lichtbedürftiger als Buchen und bieten zahlreichen Tieren Nahrung und Struktur. Eicheln werden von Tieren gefressen und teils verstreut. Alte Bäume und ihr Totholz erhalten Mikrohabitate.', 'Artenreiche Wirtsbeziehungen; Zoochorie; Sukzession.', 'https://www.waldwissen.net/de/lebensraum-wald/baeume-und-waldpflanzen/laubbaeume/traubeneiche-und-stieleiche-im-portrait'),
  plant('quercus_petraea','Traubeneiche','Quercus petraea','tree','oak',26,['forest'],'Baumschicht',['#657b42','#716448'], 'Länger gestielte Blätter; Eicheln kurz gestielt und gehäuft; kaum Blattöhrchen.', 'Traubeneichen wachsen häufig auf gut durchlüfteten Böden. Ihre Merkmale unterscheiden sich von denen der Stieleiche, auch wenn Mischformen eine Bestimmung erschweren können. Licht im Kronenraum beeinflusst ihr Wachstum.', 'Ökologische Amplitude; verwandte Arten und Hybridisierung.', 'https://www.waldwissen.net/de/lebensraum-wald/baeume-und-waldpflanzen/laubbaeume/traubeneiche-und-stieleiche-im-portrait'),
  plant('betula_pendula','Sandbirke','Betula pendula','tree','birch',22,['forest','city'],'Baumschicht',['#6f8a46','#d8d4bd'], 'Weiße Rinde mit dunklen Rissen, dreieckig-rhombische gezähnte Blätter, hängende Zweige.', 'Sandbirken besiedeln als lichtliebende Pioniere offene Flächen. Ihre kleinen geflügelten Samen verbreitet der Wind. Unter einem dichten späteren Kronendach sind sie gegenüber schattentoleranten Bäumen im Nachteil.', 'Sukzession, Ausbreitung und Lichtkonkurrenz.', flora('829')),
  plant('pinus_sylvestris','Waldkiefer','Pinus sylvestris','tree','pine',26,['forest'],'Baumschicht',['#61785b','#a27752'], 'Nadeln paarweise; orangebraune Borke im oberen Stamm; lockere hoch ansetzende Krone.', 'Waldkiefern sind lichtbedürftige Nadelbäume. Auf armen sandigen Standorten können sie bestehen, wo konkurrenzkräftige Laubbäume schlechter wachsen. Ihre Nadeln, Samen und ihr Holz sind Ressourcen für andere Organismen.', 'Abiotische Standortfaktoren und Konkurrenz.', 'https://www.waldwissen.net/de/lebensraum-wald/baeume-und-waldpflanzen/nadelbaeume/die-waldkiefer'),
  plant('alnus_glutinosa','Schwarzerle','Alnus glutinosa','tree','alder',20,['forest','lake'],'Baum- und Uferzone',['#4c703d','#686454'], 'Rundliche oft vorn ausgerandete Blätter und kleine verholzte Fruchtstände.', 'Schwarzerlen wachsen an nassen Standorten und Gewässerrändern. Ihre Wurzeln können mit stickstofffixierenden Frankia-Bakterien verbunden sein. Laub und Wurzeln beeinflussen den Stoffhaushalt im Uferbereich.', 'Symbiose und Stickstoffkreislauf.', flora(325)),
  plant('fraxinus_excelsior','Gewöhnliche Esche','Fraxinus excelsior','tree','ash',26,['forest','lake','city'],'Baumschicht',['#69834a','#807c68'], 'Gefiederte Blätter, schwarze Knospen und längliche geflügelte Früchte.', 'Eschen gehören zu frischen bis feuchten nährstoffreichen Laubwaldstandorten. Die geflügelten Früchte werden durch Wind verbreitet. Baumkrankheiten können die Zusammensetzung eines Bestandes verändern.', 'Standortansprüche und biotische Faktoren.', flora(2477)),
  plant('corylus_avellana','Gemeine Hasel','Corylus avellana','shrub','hazel',4.5,['forest','city','farmland'],'Strauchschicht',['#617942','#847258'], 'Mehrstämmiger Strauch; rundliche gezähnte Blätter, Haselnüsse in Blatthüllen.', 'Haseln wachsen an Waldsäumen und in Hecken. Ihre Nüsse liefern Tieren energiereiche Nahrung. Früh blühende Kätzchen geben Pollen an den Wind ab.', 'Struktur der Strauchschicht; Nahrung und Samenverbreitung.', flora(1676)),
  plant('crataegus_monogyna','Eingriffliger Weißdorn','Crataegus monogyna','shrub','hawthorn',4,['forest','meadow','city','farmland'],'Strauchschicht und Hecke',['#657944','#6d6555','#eae3cb'], 'Dornige Zweige, gelappte Blätter, weiße Blüten; rote Früchte mit einem Steinkern.', 'Weißdorn bildet deckungsreiche Hecken. Die Blüten bieten Insekten Nahrung und die Früchte werden von Vögeln gefressen. Nahrung und sichere Nistorte liegen hier eng beieinander.', 'Habitatstruktur; Bestäubung und Zoochorie.', flora(1709)),
  plant('sambucus_nigra','Schwarzer Holunder','Sambucus nigra','shrub','elder',5,['forest','city','farmland'],'Strauchschicht',['#54753d','#837b61','#e8e1bf'], 'Gefiederte gegenständige Blätter, breite helle Blütenstände und schwarze Früchte.', 'Holunder wächst oft an nährstoffreichen Säumen. Früchte liefern vielen Vögeln Nahrung. Die Ausscheidung der Samen kann zur Verbreitung beitragen.', 'Fruchtkonsum, Samenverbreitung und Nährstoffzeiger.', flora('5227')),
  plant('prunus_spinosa','Schlehe','Prunus spinosa','shrub','hawthorn',3,['forest','meadow','farmland'],'Hecke und Waldrand',['#5b723e','#574f43','#ede7d3'], 'Dornige Zweige, weiße Blüten vor dem Laubaustrieb, blauschwarze bereifte Früchte.', 'Schlehen bilden dichte Hecken und können über Wurzelausläufer wachsen. Ihre frühen Blüten sind eine Ressource für Insekten. Dornige Zweige bieten Deckung für brütende Vögel.', 'Vegetative Ausbreitung und Lebensraumstruktur.', flora(4599)),
  plant('rosa_canina','Hundsrose','Rosa canina','shrub','rose',2.5,['forest','meadow','city','farmland'],'Strauchschicht',['#6a8147','#86704f','#d4b6ae'], 'Bogige stachelige Zweige, gefiederte Blätter, blassrosa Blüten und rote Hagebutten.', 'Hundsrosen wachsen an hellen Säumen und in Hecken. Blüten und Hagebutten versorgen unterschiedliche Tiergruppen. Ihre stacheligen Zweige schaffen Rückzugsräume.', 'Saisonale Ressourcen und Habitatheterogenität.', flora(26665)),
  plant('anemone_nemorosa','Buschwindröschen','Anemone nemorosa','herb','flower',.20,['forest'],'Krautschicht',['#72954a','#6e7750','#efead9'], 'Weiße Einzelblüte über einem Quirl stark geteilter Blätter; flächige Bestände.', 'Buschwindröschen blühen früh im Jahr, bevor die Baumkronen stark beschatten. Ein unterirdisches Rhizom dient als Speicher und Ausbreitungsorgan. Das frühe Zeitfenster verändert die Lichtkonkurrenz.', 'Zeitliche Einnischung und Geophytenstrategie.', flora(20424)),
  plant('galium_odoratum','Waldmeister','Galium odoratum','herb','flower',.25,['forest'],'Krautschicht',['#71904d','#6e7650','#e5e5d6'], 'Schmale Blätter in Quirlen und kleine weiße Blüten; niedriger flächiger Wuchs.', 'Waldmeister wächst in frischen, häufig nährstoffreicheren Laubwäldern. Er verträgt schattige Bedingungen. Die hakigen Früchte können am Fell von Tieren haften.', 'Schattenpflanze, Zeigerwerte und epizoochore Verbreitung.', flora(20638)),
  plant('dryopteris_filix_mas','Gewöhnlicher Wurmfarn','Dryopteris filix-mas','fern','fern',1.0,['forest'],'Krautschicht',['#4f7738','#75664c'], 'Trichter aus gefiederten dunkelgrünen Wedeln; Sporenlager auf der Blattunterseite.', 'Wurmfarne wachsen an frischen schattigen Standorten. Sie bilden weder Blüten noch Samen, sondern Sporen. Die Wedel gliedern den bodennahen Lebensraum.', 'Fortpflanzungswechsel; Mikroklima der Krautschicht.', flora(2037)),
  plant('urtica_dioica','Große Brennnessel','Urtica dioica','herb','flower',1.2,['forest','city','farmland','meadow'],'Krautschicht und Saum',['#4f7634','#71704c','#80905a'], 'Gegenständige grob gezähnte Blätter und Brennhaare; unscheinbare hängende Blüten.', 'Brennnesseln sind an vielen nährstoffreichen Säumen zu finden. Ihre Blätter ernähren spezialisierte Schmetterlingsraupen. Eine unauffällige Pflanze kann deshalb eine wichtige Ressource im Lebenszyklus auffälliger Tiere sein.', 'Wirtspflanzenbindung und Stickstoff als Standortfaktor.', flora('24427')),
  plant('poa_pratensis','Wiesen-Rispengras','Poa pratensis','grass','grass',.55,['meadow','city','farmland'],'Grasschicht',['#80914f','#8a855b','#b9b28b'], 'Schmale Blätter mit kapuzenartiger Spitze, verzweigter lockerer Blütenstand.', 'Wiesen-Rispengras bildet unterirdische Ausläufer. Es wächst in Grünland und kann dichte Vegetation schaffen. Grasblüten werden überwiegend durch Wind bestäubt.', 'Vegetative Vermehrung; Windbestäubung.', flora('4368')),
  plant('festuca_rubra','Rotschwingel','Festuca rubra','grass','grass',.55,['meadow','beach','wadden','forest'],'Grasschicht',['#718655','#857353','#a7a681'], 'Feine Blätter und schmale Rispen; dichter bis lockerer Rasen.', 'Rotschwingel wächst an sehr unterschiedlichen offenen Standorten. An Küsten bilden angepasste Formen Bestände in höher gelegenen Salzwiesen. Die genaue Unterart lässt sich aus einer entfernten Silhouette nicht sicher bestimmen.', 'Ökologische Amplitude und Grenzen der Feldbestimmung.', flora('2421')),
  plant('dactylis_glomerata','Gewöhnliches Knaulgras','Dactylis glomerata','grass','grass',1.0,['meadow','farmland'],'Grasschicht',['#7c8e58','#918266','#b7b797'], 'Graugrüne breitere Blätter, dicht geknäuelte Teilblütenstände und abgeflachte Halme.', 'Knaulgras wächst auf frischen häufig nährstoffreichen Wiesen und an Säumen. Seine größeren Halme konkurrieren mit niedrigeren Kräutern um Licht. Mahd verändert dieses Verhältnis.', 'Lichtkonkurrenz und Störung im Grünland.', flora(1843)),
  plant('trifolium_pratense','Rotklee','Trifolium pratense','herb','flower',.35,['meadow','city','farmland'],'Krautschicht',['#718948','#7c7651','#b58195'], 'Dreiteilige Blätter häufig mit heller Zeichnung; rotviolette kugelige Blütenköpfe.', 'Rotklee bietet vielen Hummeln Pollen und Nektar. Knöllchenbakterien an den Wurzeln können Luftstickstoff binden. Der Nutzen einer Blüte und der Einfluss auf den Nährstoffhaushalt sind verschiedene Wechselwirkungen.', 'Mutualismus; Bestäubung und Stickstofffixierung.', flora(6057)),
  plant('leucanthemum_vulgare','Frühe Margerite','Leucanthemum vulgare','herb','flower',.55,['meadow','city','farmland'],'Krautschicht',['#74844d','#867c51','#eee7d0'], 'Weiße Zungenblüten um gelbes Zentrum; längliche teils gelappte Blätter.', 'Die Margerite besitzt einen Blütenkorb aus vielen kleinen Einzelblüten. Verschiedene Insekten besuchen ihn. In artenreichem Grünland wächst sie zwischen Gräsern und anderen Kräutern.', 'Blütenökologie und Konkurrenz im Grünland.', flora(22456)),
  plant('achillea_millefolium','Gewöhnliche Schafgarbe','Achillea millefolium','herb','flower',.55,['meadow','city','farmland'],'Krautschicht',['#7b8957','#8b805a','#e3ddc9'], 'Fein gefiederte Blätter; viele kleine weißliche Blütenkörbe in flacher Gruppe.', 'Schafgarben nutzen offene Wiesen und Säume. Die flach zugänglichen Blütenstände werden von verschiedenen Insekten besucht. Der fein gegliederte Blattbau erleichtert die Bestimmung gegenüber grobblättrigen Wiesenkräutern.', 'Bestäubernetz und funktionelle Vielfalt.', flora(26082)),
  plant('plantago_lanceolata','Spitzwegerich','Plantago lanceolata','herb','flower',.35,['meadow','city','farmland'],'Kraut- und Wegsaum',['#7d8b56','#837657','#c5b58b'], 'Lanzettliche grundständige Blätter mit parallelen Nerven; kurzer dunkler Ährenkopf.', 'Spitzwegerich wächst in Grünland und an Wegen. Die Blattstellung am Boden kann nach Schnitten weiter erhalten bleiben. Die kleinen Blüten sind auf Windbestäubung ausgerichtet.', 'Anpassung an Mahd und Verteilung von Wachstumspunkten.', flora(26022)),
  plant('phragmites_australis','Gewöhnliches Schilf','Phragmites australis','reed','reed',2.5,['lake','forest'],'Röhrichtzone',['#8b9459','#a8976b','#b7ad90'], 'Hohe Halme mit breiten Blättern und federartigen Rispen; dichter Röhrichtgürtel.', 'Schilf wächst an nassen Ufern und breitet sich über Rhizome aus. Seine Halme bieten Deckung und Struktur. Abgestorbene Pflanzenteile gehen in das Detritusnetz über.', 'Zonierung im Litoral und vegetative Konkurrenz.', flora(4229)),
  plant('typha_latifolia','Breitblättriger Rohrkolben','Typha latifolia','reed','reed',2.0,['lake','forest'],'Röhrichtzone',['#6d8757','#8f8060','#5c4b37'], 'Breite bandförmige Blätter und brauner zylindrischer Kolben am aufrechten Stängel.', 'Rohrkolben besiedeln nährstoffreichere flache Ufer. Unterirdische Rhizome verbinden viele Triebe. Luftleitende Gewebe unterstützen das Leben im nassen Boden.', 'Anpassung an Sauerstoffmangel im Wurzelraum.', flora(6127)),
  plant('nymphaea_alba','Weiße Seerose','Nymphaea alba','aquatic','seagrass',.25,['lake','forest'],'Schwimmblattzone',['#5f7c49','#817250','#efebd6'], 'Runde tief eingeschnittene Schwimmblätter und große weiße Blüten auf dem Wasser.', 'Seerosen wurzeln im Gewässergrund und tragen Blätter an der Oberfläche. Die Schwimmblätter erreichen Licht oberhalb der Wassersäule. Unter ihnen entstehen beschattete Rückzugsräume.', 'Funktionsmorphologie und Licht als abiotischer Faktor.', flora(3859)),
  plant('ceratophyllum_demersum','Raues Hornblatt','Ceratophyllum demersum','aquatic','seagrass',.75,['lake','forest'],'Tauchblattzone',['#4d7246','#647756'], 'Untergetauchte mehrfach gegabelte schmale Blätter in Quirlen; dicht verzweigte Sprosse.', 'Hornblatt wächst vollständig unter Wasser und besitzt keine echten Wurzeln. Die Triebe bieten kleinen Tieren und Jungfischen Struktur. Lichtangebot und Nährstoffe beeinflussen die Bestände.', 'Unterwasserhabitat; Ressourcen und Stoffhaushalt.', flora('1468')),
  plant('ammophila_arenaria','Gewöhnlicher Strandhafer','Ammophila arenaria','grass','grass',.90,['beach'],'Weißdüne',['#929a68','#b1a279','#c8ba93'], 'Dichte Horste, steife oft eingerollte Blätter und kompakte hellbeige Blütenstände.', 'Strandhafer bindet mit seinem Wurzelsystem Sand und wächst bei weiterer Übersandung nach. Seine Horste bremsen Wind und fördern Sandablagerung. Damit verändert die Pflanze ihren eigenen Standort.', 'Ökosystemingenieur; positive Rückkopplung und Dünenbildung.', flora(384)),
  plant('hippophae_rhamnoides','Sanddorn','Hippophae rhamnoides','shrub','hawthorn',3.0,['beach'],'Dünengebüsch',['#99a488','#8b8271','#c48a4f'], 'Dornige Zweige, schmale silbriggrüne Blätter; orange Früchte an weiblichen Pflanzen.', 'Sanddorn wächst in hellen Dünen- und Pioniergebüschen. Seine Früchte liefern Vögeln Nahrung. Stickstofffixierende Wurzelsymbionten beeinflussen die Nutzung nährstoffarmer Standorte.', 'Pionierpflanze; Symbiose und Zoochorie.', flora('2962')),
  plant('cakile_maritima','Europäischer Meersenf','Cakile maritima','succulent','flower',.25,['beach'],'Spülsaum',['#95a587','#a79d74','#c4afbb'], 'Fleischige graugrüne Blätter, kleine blasslila Kreuzblüten, gegliederte Früchte.', 'Meersenf nutzt nährstoffreiche Spülsäume an Küsten. Dort lagern Wellen organisches Material ab und schaffen zugleich Störungen. Die Pflanze wächst in offenen Flächen statt unter einem geschlossenen Grasbestand.', 'Pionierbesiedlung, Detrituseintrag und Störung.', flora('20885')),
  plant('tripleurospermum_maritimum','Echte Strandkamille','Tripleurospermum maritimum','herb','flower',.25,['beach'],'Spülsaum',['#879366','#9b8f65','#eee7d0'], 'Niedriger verzweigter Wuchs, fein geteilte fleischige Blätter, weiß-gelbe Blütenkörbe.', 'Strandkamille wächst an Küsten-Spülsäumen und salzbeeinflussten Standorten. Sie verträgt Bedingungen, die viele Wiesenpflanzen begrenzen. Die kleinen Blütenkörbe werden von Insekten besucht.', 'Salzeinfluss und ökologische Toleranz.', flora('6098')),
  plant('salicornia_europaea','Gewöhnlicher Queller','Salicornia europaea','succulent','queller',.22,['wadden'],'Pionierzone der Salzwiese',['#91a05d','#99814d','#bc8a68'], 'Fleischige gegliederte Sprosse, stark reduzierte Blätter; rötliche Herbstfärbung.', 'Queller besiedelt regelmäßig salzwasserbeeinflusste Böden. Wasserspeicherndes Gewebe ist Teil seiner Salztoleranz. Verwandte Quellerarten sind schwer zu bestimmen; der Eintrag kennzeichnet den dargestellten Modelltyp.', 'Halophyten; osmotischer Stress und Zonierung.', flora(11824)),
  plant('limonium_vulgare','Gewöhnlicher Strandflieder','Limonium vulgare','herb','flower',.35,['wadden'],'Salzwiese',['#8b9e75','#998969','#a997bf'], 'Rosette länglicher Blätter; locker verzweigte violette Blütenstände.', 'Strandflieder ist eine charakteristische Pflanze toniger Salzwiesen. Unterschiedliche Überflutung und Salzbelastung begrenzen seine Verteilung. Er ist kein Gehölz und nicht eng mit dem Gartenflieder verwandt.', 'Ökologische Potenz; Standortgradienten.', flora(3411)),
  plant('zostera_marina','Gewöhnliches Seegras','Zostera marina','aquatic','seagrass',.75,['wadden','beach'],'Seegraswiese',['#7c956b','#92a37a'], 'Untergetauchte bandförmige Blätter aus einem Rhizom; größere Seegrasart.', 'Seegras ist eine Blütenpflanze und keine Alge. Seine Bestände bieten Fischen und Wirbellosen Nahrung, Versteck und Laichmöglichkeiten. Lichtdurchlässiges flaches Küstenwasser fördert die Photosynthese.', 'Habitatbildung; Lichtlimitierung und Schutzfunktion.', coast+'wissensbeitrag/lebensraum-seegraswiese/'),
  plant('zostera_noltei','Zwerg-Seegras','Zostera noltei','aquatic','seagrass',.22,['wadden'],'Gezeiten-Seegraswiese',['#8aa373','#94a67d'], 'Sehr schmale kurze Blattbänder; niedrige Bestände im flachen Gezeitenbereich.', 'Zwerg-Seegras kann im Gezeitenbereich beim Niedrigwasser trockenfallen. Es schafft im Watt zusätzliche Struktur. Die Art wird in älteren Quellen auch als Zostera noltii bezeichnet.', 'Gezeitenanpassung und Habitatheterogenität.', coast+'wissensbeitrag/lebensraum-seegraswiese/'),
  plant('elymus_athericus','Strandquecke','Elymus athericus','grass','grass',.80,['wadden'],'Obere Salzwiese',['#95a078','#ac9d77','#c0b397'], 'Graugrüne bis grüne Blätter, lange Ähren und dichte über Ausläufer verbundene Bestände.', 'Strandquecke bildet häufig dichte Bestände in höher gelegenen Salzwiesen. Häufig überflutete tiefere Flächen begrenzen sie stärker. Unterirdische Ausläufer erlauben eine kräftige vegetative Ausbreitung.', 'Konkurrenz und Zonierung entlang eines Überflutungsgradienten.', coast+'sh/naturerlebnisraum-spo/strandquecke/'),
  plant('papaver_rhoeas','Klatschmohn','Papaver rhoeas','herb','flower',.60,['farmland'],'Acker- und Feldsaum',['#7c895b','#938464','#be644d'], 'Rote vierteilige Blüten, behaarte Stängel, schwarze Flecken oft am Blütengrund.', 'Klatschmohn ist eine einjährige Art offener gestörter Böden. Seine Samen können im Boden überdauern. Bearbeitung kann neue Keimstellen schaffen, während Konkurrenz oder Herbizide das Aufwachsen begrenzen.', 'Samenbank; Störung und wechselnde Selektionsbedingungen.', 'https://www.floraweb.de/'),
  plant('centaurea_cyanus','Kornblume','Centaurea cyanus','herb','flower',.65,['farmland'],'Acker- und Feldsaum',['#8a9773','#9b8f67','#6e91b9'], 'Blaue Blütenkörbe, schmale graugrüne Blätter, aufrechter verzweigter Wuchs.', 'Kornblumen gehören zu den bekannten Begleitpflanzen von Äckern. Licht, Bodenbearbeitung und Konkurrenz beeinflussen ihre Entwicklung. Blühende Säume ergänzen Nahrung für Insekten.', 'Agrarökologie, Biodiversität und Nutzungskonflikte.', 'https://www.floraweb.de/'),
  plant('triticum_aestivum','Saatweizen','Triticum aestivum','grass','grass',.85,['farmland'],'Kulturpflanzenbestand',['#a4a66a','#b8a571','#c6b382'], 'Aufrechte Ähre mit dicht sitzenden Körnern; hier kurz begrannte Kulturform.', 'Weizen ist eine domestizierte Kulturpflanze. Der Anbau bündelt Biomasse auf großer Fläche, doch ein gleichförmiger Bestand bietet anderen Arten nicht alle benötigten Ressourcen. Feldsäume und Hecken ergänzen das Habitat.', 'Domestikation, Agroökosystem und Biomasseproduktion.', 'https://www.julius-kuehn.de/'),
  plant('polytrichum_commune','Goldenes Frauenhaarmoos','Polytrichum commune','moss','moss',.12,['forest'],'Moosschicht',['#64834e','#817154'], 'Aufrechte sternförmig beblätterte Triebe, bei trockenem Zustand dichter anliegende Blätter.', 'Dieses Moos wächst häufig an feuchten eher sauren Standorten. Es besitzt keine Blüten und verbreitet sich durch Sporen. Dichte Polster verändern das bodennahe Feuchte- und Temperaturmilieu.', 'Mikroklima; andere Fortpflanzungsweise als Samenpflanzen.', 'https://www.waldwissen.net/'),
  plant('fomes_fomentarius','Zunderschwamm','Fomes fomentarius','fungus','fungus',.25,['forest'],'Totholzschicht',['#9b9582','#786e56','#c2bba3'], 'Harte mehrjährige hufförmige Fruchtkörper an Laubholz, graue konzentrische Zonen.', 'Der Zunderschwamm ist ein Pilz und betreibt keine Photosynthese. Sein Myzel baut Holzbestandteile ab. Die sichtbaren Fruchtkörper sind nur ein Teil des Organismus.', 'Destruenten; Stoffkreislauf und Pilzreich.', 'https://www.waldwissen.net/de/lebensraum-wald/baeume-und-waldpflanzen/die-buche-baum-des-jahres-2022'),
];
