PLANTS.fomes_fomentarius.source = 'https://www.dgfm-ev.de/de/ueber-uns/news/pilz-des-jahres-1995-zunderschwamm';
for (const id of ['phragmites_australis','typha_latifolia','nymphaea_alba']) PLANTS[id].habitats.push('city');

